"use client";

/**
 * Egypt by governorate, shaded by players per million people (the federation home). The shapes
 * come from egypt-map-data.ts (Natural Earth, public domain, generated by
 * data/pipelines/geo/egypt_map.py).
 *
 * "Thin" is the same rule RatioBars uses (THIN_SHARE of the best-covered governorate), so the map
 * and the ranked list beside it never disagree. A governorate with no tracked players at all has
 * its own colour, so a gap reads as a gap. The Delta governorates and Cairo are small at this
 * size, which is why the map sits beside the list rather than replacing it: the map shows where,
 * the list gives the numbers.
 */

import { useState } from "react";
import { THIN_SHARE } from "./charts";
import { EGYPT_VIEWBOX, GOVERNORATE_PATHS } from "./egypt-map-data";

export interface MapRow {
  code: string;
  label: string;
  /** Players tracked in the governorate. */
  players: number;
  /** Population in millions. */
  populationM: number;
}

/** From just above thin to the best covered, in the bars' sky; thin in their amber. */
const STEPS = ["#0284c7", "#0ea5e9", "#38bdf8", "#7dd3fc", "#bae6fd"];
const NONE = "#1e293b";
const THIN = "#f59e0b";

function perMillion(r: MapRow) {
  return r.players / r.populationM;
}

function caption(r: MapRow) {
  if (r.players === 0) return "no tracked players";
  const ratio = perMillion(r);
  return `${r.players} ${r.players === 1 ? "player" : "players"}, ${ratio < 10 ? ratio.toFixed(1) : ratio.toFixed(0)} per million people`;
}

export function EgyptMap({ rows }: { rows: MapRow[] }) {
  const [hover, setHover] = useState<string | null>(null);
  const byCode = Object.fromEntries(rows.map((r) => [r.code, r]));
  // As RatioBars: at least 1, so a sport with no players anywhere does not divide by 0.
  const max = Math.max(1, ...rows.map(perMillion));
  const thinBelow = THIN_SHARE * max;

  const fill = (row: MapRow | undefined) => {
    if (!row || row.players === 0) return NONE;
    const ratio = perMillion(row);
    if (ratio < thinBelow) return THIN;
    const t = (ratio - thinBelow) / (max - thinBelow || 1);
    return STEPS[Math.min(STEPS.length - 1, Math.floor(t * STEPS.length))];
  };

  const shown = hover ? byCode[hover] : undefined;

  return (
    <div>
      <svg
        viewBox={EGYPT_VIEWBOX}
        className="h-auto w-full"
        role="img"
        aria-label="Map of Egypt's governorates shaded by players tracked per million people"
        onMouseLeave={() => setHover(null)}
      >
        {Object.entries(GOVERNORATE_PATHS).map(([code, shape]) => {
          const row = byCode[code];
          return (
            <path
              key={code}
              d={shape.d}
              fill={fill(row)}
              stroke={hover === code ? "#f8fafc" : "#020617"}
              strokeWidth={hover === code ? 2 : 0.8}
              strokeLinejoin="round"
              onMouseEnter={() => setHover(code)}
              data-code={code}
            >
              <title>{row ? `${row.label}: ${caption(row)}` : shape.name}</title>
            </path>
          );
        })}
        {/* Drawn again on top so its outline is not hidden under a neighbour's. */}
        {hover && GOVERNORATE_PATHS[hover] ? (
          <path
            d={GOVERNORATE_PATHS[hover].d}
            fill="none"
            stroke="#f8fafc"
            strokeWidth={2}
            strokeLinejoin="round"
            pointerEvents="none"
          />
        ) : null}
      </svg>
      <p className="mt-2 h-5 text-sm text-slate-300" aria-live="polite">
        {shown ? (
          <>
            <span className="font-semibold">{shown.label}</span>
            <span className="text-slate-400">: {caption(shown)}</span>
          </>
        ) : (
          <span className="text-slate-500">Point at a governorate for its numbers.</span>
        )}
      </p>
      <div className="mt-2 flex flex-wrap items-center gap-x-4 gap-y-2 text-xs text-slate-500">
        <span className="flex items-center gap-1.5">
          <span className="inline-block h-2.5 w-2.5 rounded-sm ring-1 ring-slate-600" style={{ background: NONE }} />
          none
        </span>
        <span className="flex items-center gap-1.5">
          <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: THIN }} />
          thin
        </span>
        <span className="flex items-center gap-1.5">
          <span className="flex overflow-hidden rounded-sm">
            {STEPS.map((c) => (
              <span key={c} className="inline-block h-2.5 w-3" style={{ background: c }} />
            ))}
          </span>
          more per million people
        </span>
      </div>
    </div>
  );
}
